import importlib; import sys; 
if 'semver' in sys.modules:
    del sys.modules['semver']

import semver
import subprocess, traceback

results = {}

# Test R1a: pysemver without args → SystemExit
r = subprocess.run([sys.executable, "-c", """
import sys; sys.path.insert(0,'.'); import semver; semver.main([])
"""], capture_output=True, text=True)
results["R1a_no_args"] = {"rc": r.returncode, "stderr_head": r.stderr[:200]}

# Test R1b: bump without sub-subcommand → help + exit
r = subprocess.run([sys.executable, "-c", """
import sys; sys.path.insert(0,'.'); import semver; semver.main(['bump'])
"""], capture_output=True, text=True)
results["R1b_bump_help"] = {"rc": r.returncode, "stdout_has_usage": "usage:" in r.stdout}

# Test R2: regex for semver.org compliance  
# Check what regex is used
import re
content = open("semver.py").read()
# Find version pattern
match = re.search(r'_VERSION_PATTERN\s*=\s*r\("(.*?)"', content)
results["R2_regex"] = {"pattern": match.group(1) if match else "NOT FOUND"}

# Test R3: VersionInfo.isvalid() exists
try:
    result = semver.VersionInfo.isvalid("1.2.3")
    results["R3_isvalid"] = {"exists": True, "result_123": result, "result_invalid": semver.VersionInfo.isvalid("invalid")}
except Exception as e:
    results["R3_isvalid"] = {"error": str(e)}

# Test R4: Public API exports
for name in ["cmd_bump", "cmd_check", "cmd_compare"]:
    results[f"R4_{name}"] = {"exists": hasattr(semver, name), "callable": callable(getattr(semver, name, None))}

str(results)
